#!/usr/bin/env bash
#
# Runs the standard `devcontainer features test` harness. Unlike
# shared-agent-config this feature declares no mounts, so nothing here can
# touch a production volume and src/ is used directly.
#
# On Colima/Lima the CLI's workspace bind-mount needs TMPDIR under $HOME.
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
case "${TMPDIR:-}" in
    "$HOME"/*) ;;
    *) export TMPDIR="$HOME/tmp"; mkdir -p "$TMPDIR" ;;
esac

devcontainer features test \
    --project-folder "$REPO_ROOT" \
    --features opencode \
    --skip-autogenerated \
    "$@"
